/* Captors keep a reference to their opponent's fighter; shared opponent originals stay read only. */
(function(){
'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`;
const T=(en,ko)=>window.UKI18n?.language==='en'?en:ko;
const flagged=v=>v===true||v==='true',key=c=>c.remoteCampaignId||c.id,ed=g=>String(g?.edition||'').toUpperCase();
const me=()=>window.AccountParity?.account?.id||'';
const owned=g=>!!g&&!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===me());
const identity=g=>({sourceId:g.sourceGangId||g.id,ownerId:g.sourceOwnerId||g.ownerId||g.remoteOwnerId||me()});
const same=(g,target)=>g&&(g.sourceGangId||g.id)===target.sourceId&&(!target.ownerId||!identity(g).ownerId||identity(g).ownerId===target.ownerId);
function gangs(c){const result=[];for(const m of c?.members||[]){const linked=data.gangs.find(g=>g.id===m.gangId);if(!linked||ed(linked)!==ed(c))continue;const original=linked.remoteReadOnly&&identity(linked).ownerId===me()?data.gangs.find(g=>owned(g)&&g.id===linked.sourceGangId):null,g=original||linked;if(!result.some(row=>same(row,identity(g))))result.push(g);}return result;}
function targetOf(c,r){const g=gangs(c).find(g=>same(g,r.target));return {g,f:g?.fighters?.find(f=>f.id===r.target.fighterId)};}
function active(c,r){if(r.releasedAt||r.campaignId!==key(c))return false;const {g,f}=targetOf(c,r);return !(r.rosterApplied&&owned(g)&&f&&f.status!=='Captured'&&!flagged(f.captured));}
function records(c){return gangs(c).flatMap(holder=>(holder.campaignCaptives||[]).filter(r=>active(c,r)).map(record=>({holder,record,...targetOf(c,record)})));}
function unavailable(c,g,f){
 if(['Dead','Destroyed','Retired','Enslaved'].includes(f.status)||['killed','destroyed','retired','enslaved'].some(k=>flagged(f[k])))return T('No longer an eligible fighter','생포 대상으로 선택할 수 없는 상태');
 if(f.status==='Captured'||flagged(f.captured)||records(c).some(r=>same(g,r.record.target)&&r.record.target.fighterId===f.id))return T('Already captured','이미 생포됨');
 return '';
}
function button(action,en,ko,attrs='',disabled=false){return `<button type="button" class="btn small" data-campaign-captive="${action}" ${attrs} ${disabled?'disabled':''}>${L(en,ko)}</button>`;}
function section(c){
 const rows=records(c),legacy=gangs(c).flatMap(g=>(g.fighters||[]).filter(f=>(f.status==='Captured'||flagged(f.captured))&&!rows.some(r=>same(g,r.record.target)&&r.record.target.fighterId===f.id)).map(f=>({g,f})));
 const html=rows.map(({holder,record:r,g,f})=>`<article class="ccap-row"><div><strong data-user-text>${E(f?.name||r.target.name)}</strong><small><span data-user-text>${E(g?.name||r.target.gangName)}</span> → <span data-user-text>${E(holder.name)}</span></small>${!r.rosterApplied?`<small class="muted">${L('Capture recorded here · original roster status is managed by its owner','캠페인 생포 기록 · 원본 상태는 소유자가 관리')}</small>`:''}${!f?`<small class="muted">${L('Fighter is not in the current shared roster. The recorded identity is retained.','현재 공유 명단에서 파이터를 찾을 수 없어 등록 당시 기록을 표시합니다.')}</small>`:''}</div><div class="ccap-actions">${f?button('view','View fighter','파이터 보기',`data-campaign-id="${E(c.id)}" data-holder="${E(holder.id)}" data-record="${E(r.id)}"`):''}${button('release','Record release','해제 기록',`data-campaign-id="${E(c.id)}" data-holder="${E(holder.id)}" data-record="${E(r.id)}"`,!owned(holder))}</div></article>`).join('')+legacy.map(({g,f})=>`<article class="ccap-row"><div><strong data-user-text>${E(f.name)}</strong><small data-user-text>${E(g.name)}</small><small>${L('Captured in roster · captor not recorded here','로스터 생포 상태 · 생포한 갱은 미등록')}</small></div>${button('legacy-release','Record release','해제 기록',`data-campaign-id="${E(c.id)}" data-gang="${E(g.id)}" data-fighter="${E(f.id)}"`,!owned(g))}</article>`).join('');
 return `<section class="card"><h2>Captured Fighters</h2><div class="ccap-panel"><div class="ccap-toolbar">${button('add','Select from opponent roster','상대 로스터에서 선택',`data-campaign-id="${E(c.id)}"`,c.phase==='Closed'||!gangs(c).some(owned))}</div>${html||`<p class="muted"><i>${L('No fighters are currently held captive by gangs in this campaign.','현재 이 캠페인의 갱이 잡고 있는 생포 파이터가 없습니다.')}</i></p>`}</div></section>`;
}
function submitLabel(en,ko){const b=document.getElementById('modal-submit');b.dataset.i18nEn=en;b.dataset.i18nKo=ko;b.textContent=T(en,ko);}
function error(message){const node=document.querySelector('.ccap-error');if(node){node.hidden=false;node.textContent=message;}return false;}
function open(campaignId,previous={}){
 const c=data.campaigns.find(c=>c.id===campaignId);if(!c||c.phase==='Closed')return;
 const holders=gangs(c).filter(owned),holder=holders.find(g=>g.id===previous.holderId)||holders[0];if(!holder)return;
 const opponents=gangs(c).filter(g=>!same(g,identity(holder))),opponent=opponents.find(g=>g.id===previous.opponentId)||opponents[0];
 const draft={holderId:holder.id,opponentId:opponent?.id||'',query:previous.query||'',fighterId:previous.fighterId||'',note:previous.note||''};
 closeModal();formModal(L('Select captured opponent','생포한 상대 파이터 선택'),`<div class="ccap-picker wide"><div class="ccap-selectors"><label>${L('Capturing gang','생포한 갱')}<select name="captureHolder">${holders.map(g=>`<option value="${E(g.id)}" ${g===holder?'selected':''} data-user-text>${E(g.name)}</option>`).join('')}</select></label><label>${L('Opponent roster','상대 로스터')}<select name="captureOpponent">${opponents.map(g=>`<option value="${E(g.id)}" ${g===opponent?'selected':''} data-user-text>${E(g.name)}</option>`).join('')}</select></label></div><input type="search" name="captureSearch" value="${E(draft.query)}" placeholder="Search opponent fighters" aria-label="Search opponent fighters" data-i18n-ko-placeholder="상대 파이터 이름·유형 검색" data-i18n-ko-aria-label="상대 파이터 이름·유형 검색"><p class="ccap-count muted" role="status"></p><div class="ccap-roster" role="group" aria-label="Opponent fighters" data-i18n-ko-aria-label="상대 파이터 목록"></div><label>${L('Capture note (optional)','생포 메모(선택)')}<textarea name="captureNote" maxlength="500">${E(draft.note)}</textarea></label><label class="checkline"><input type="checkbox" name="captureConfirmed" value="yes">${L('The battle / injury result actually captured this fighter.','전투·부상 결과에 따라 실제 생포된 파이터임을 확인합니다.')}</label><details class="ccap-help"><summary>${L('What is saved · example','저장되는 내용·예시')}</summary><p>${L('Choose the gang holding the captive, then the opponent and fighter. The fighter stays on the opponent’s roster; no recruit, money, XP or equipment transfer is created.','생포한 갱 → 상대 갱 → 파이터 순서로 고릅니다. 파이터는 상대 로스터에 남으며, 새 모집·크레딧·XP·장비 이동을 만들지 않습니다.')}</p><p>${L('Example: Cawdor captures Delaque’s Shade. Select Cawdor as captor, Delaque as opponent, then Shade. The campaign lists Shade under Cawdor’s captives.','예: 커도르가 델라쿠의 쉐이드를 생포했다면 생포한 갱은 커도르, 상대는 델라쿠, 파이터는 쉐이드를 선택합니다. 캠페인 생포 목록에 쉐이드와 두 갱이 함께 표시됩니다.')}</p><p>${L('The captive reference is saved in the capturing gang’s original roster and follows its normal account sync. Editable local opponent rosters also receive Captured status. For another player’s shared roster, its owner manages the original status; the capture reference remains visible without editing their personal document.','생포 기록은 생포한 갱의 원본 명단에 저장되어 기존 계정 동기화를 따릅니다. 직접 수정 가능한 상대 명단에는 생포 상태도 반영합니다. 다른 플레이어의 공유 명단은 원본 상태를 소유자가 관리하며, 상대 개인 기록을 바꾸지 않고 생포 연결을 표시합니다.')}</p><p>${L('This records a result; it does not roll or resolve capture, escape or ransom rules. Record a release only after the applicable result has been resolved.','결과를 기록하는 기능이며 생포·탈출·몸값 판정을 대신 굴리거나 처리하지 않습니다. 해당 결과를 처리한 뒤 해제를 기록하세요.')}</p></details><p class="ccap-error" role="alert" hidden></p></div>`,v=>{
  const current=data.campaigns.find(x=>x.id===campaignId),currentHolder=current&&gangs(current).find(g=>g.id===v.captureHolder&&owned(g)),currentOpponent=current&&gangs(current).find(g=>g.id===v.captureOpponent),f=currentOpponent?.fighters?.find(f=>f.id===draft.fighterId);
  if(current!==c||currentHolder!==holder||currentOpponent!==opponent||c.phase==='Closed'||data.view!=='campaign'||data.selectedCampaign!==c.id)return error(T('The campaign roster changed. Reopen this form.','캠페인 명단이 변경되었습니다. 창을 다시 여세요.'));
  if(!f||same(currentOpponent,identity(currentHolder)))return error(T('Choose a fighter from an opposing gang.','상대 갱의 파이터를 선택하세요.'));
  const reason=unavailable(c,currentOpponent,f);if(reason)return error(reason);
  if(v.captureConfirmed!=='yes')return error(T('Confirm the actual capture result.','실제 생포 결과를 확인하세요.'));
  const r={id:id(),campaignId:key(c),capturedAt:now(),releasedAt:null,target:{...identity(currentOpponent),fighterId:f.id,name:f.name,gangName:currentOpponent.name},note:String(v.captureNote||'').slice(0,500),rosterApplied:owned(currentOpponent)};
  if(r.rosterApplied){const fields=['status','captured','capturedBy','captured_by_gang_id','campaignCaptureId'];r.beforeState=Object.fromEntries(fields.filter(k=>Object.hasOwn(f,k)).map(k=>[k,f[k]]));f.status='Captured';f.captured=true;f.capturedBy=holder.id;f.captured_by_gang_id=holder.id;f.campaignCaptureId=r.id;log(currentOpponent,`${f.name}: captured by ${holder.name}`);}
  holder.campaignCaptives??=[];holder.campaignCaptives.push(r);log(holder,`${c.name}: captured ${f.name} (${currentOpponent.name})`);save();return true;
 },'Record capture');submitLabel('Record capture','생포 등록');
 const form=document.querySelector('#modal-form');form.classList.remove('two');document.querySelector('.modal').classList.add('ccap-modal');
 const roster=form.querySelector('.ccap-roster');
 function draw(){const q=draft.query.trim().toLowerCase(),list=(opponent?.fighters||[]).filter(f=>!q||[f.name,f.type].some(s=>String(s||'').toLowerCase().includes(q))||window.UKI18n?.matches(f.type||'',q));form.querySelector('.ccap-count').innerHTML=`${L('Opponent fighters','상대 파이터')} ${list.length}`;roster.innerHTML=list.map(f=>{const reason=unavailable(c,opponent,f);return `<label class="ccap-choice ${reason?'is-disabled':''}"><input type="radio" name="captureFighter" value="${E(f.id)}" ${f.id===draft.fighterId?'checked':''} ${reason?'disabled':''}><span><strong data-user-text>${E(f.name)}</strong><small data-i18n-catalog-name="${E(f.type||'')}">${E(f.type||'')}</small><small>${L('Status','상태')}: <span>${E(f.status||'Active')}</span>${reason?` · ${E(reason)}`:''}</small></span></label>`;}).join('')||`<p class="muted">${L('No fighters match this opponent roster.','상대 로스터에 조건에 맞는 파이터가 없습니다.')}</p>`;window.UKI18n?.refresh(form);}
 const read=()=>{draft.note=form.elements.captureNote.value;};
 form.elements.captureHolder.addEventListener('change',e=>{read();open(c.id,{...draft,holderId:e.target.value,opponentId:'',fighterId:''});});
 form.elements.captureOpponent.addEventListener('change',e=>{read();open(c.id,{...draft,opponentId:e.target.value,fighterId:''});});
 form.elements.captureSearch.addEventListener('input',e=>{draft.query=e.target.value;draft.fighterId='';draw();});
 roster.addEventListener('change',e=>{if(e.target.name==='captureFighter')draft.fighterId=e.target.value;});
 draw();window.UKI18n?.refresh();
}
function restore(f,r,holder){if(!r.rosterApplied||f?.campaignCaptureId!==r.id)return;if(f.status==='Captured'){for(const k of ['status','captured','capturedBy','captured_by_gang_id','campaignCaptureId']){if(Object.hasOwn(r.beforeState||{},k))f[k]=r.beforeState[k];else delete f[k];}}else{delete f.campaignCaptureId;if(f.capturedBy===holder.id){f.captured=false;f.capturedBy='';f.captured_by_gang_id=null;}}}
function release(c,holder,r){if(!owned(holder)||!active(c,r))return;const {g,f}=targetOf(c,r);closeModal();showModal(L('Record resolved release','생포 해제 결과 기록'),`<p><strong data-user-text>${E(f?.name||r.target.name)}</strong></p><p>${L('Confirm the applicable rescue, escape or ransom result was resolved. This clears the capture record; money and rewards are recorded separately.','구출·탈출·몸값 등 해당 결과를 먼저 처리했는지 확인하세요. 생포 연결을 해제하며 돈과 보상은 별도로 기록합니다.')}</p>`,'Record release',()=>{if(!owned(holder)||!active(c,r))return false;r.releasedAt=now();if(owned(g))restore(f,r,holder);log(holder,`${c.name}: released ${f?.name||r.target.name}`);save();return true;});submitLabel('Record release','해제 기록');window.UKI18n?.refresh();}
function view(c,holder,r,b){const {g,f}=targetOf(c,r);if(!f)return;const body=`<p><strong data-user-text>${E(f.name)}</strong> · <span data-user-text>${E(g.name)}</span></p><p><span data-i18n-catalog-name="${E(f.type||'')}">${E(f.type||'')}</span></p><p>${L('Held by','생포한 갱')}: <span data-user-text>${E(holder.name)}</span></p><p>${L('Equipment','장비')}: ${(f.equipment||[]).map(e=>`<span data-user-text>${E(e.name)}</span>`).join(', ')||'—'}</p>${r.note?`<p class="ccap-note" data-user-text>${E(r.note)}</p>`:''}`;window.MMRuleReference?.openContext('Captured fighter',body,{nameKo:'생포된 파이터',activator:b});}
function legacyRelease(c,g,f){if(!owned(g)||!f)return;closeModal();showModal(L('Record resolved release','생포 해제 결과 기록'),`<p><strong data-user-text>${E(f.name)}</strong></p><p>${L('Confirm the rescue, escape or ransom result was resolved. Remove the captured status from this owned roster?','구출·탈출·몸값 결과를 먼저 처리했는지 확인하세요. 이 원본 로스터의 생포 상태를 해제할까요?')}</p>`,'Record release',()=>{if(!owned(g)||!gangs(c).includes(g)||!g.fighters.includes(f))return false;const injuryIds=new Set((f.injuries||[]).filter(i=>i.name==='Captured'||flagged((i.typeSpecificData||i.type_specific_data||{}).captured)).map(i=>i.id));f.injuries=(f.injuries||[]).filter(i=>!injuryIds.has(i.id));f.effects=(f.effects||[]).filter(i=>!injuryIds.has(i.injuryId));if(f.status==='Captured')f.status=flagged(f.recovery)?'In Recovery':'Active';f.captured=false;f.capturedBy='';f.captured_by_gang_id=null;delete f.campaignCaptureId;log(g,`${c.name}: ${f.name} released`);save();return true;});submitLabel('Record release','해제 기록');window.UKI18n?.refresh();}
window.addEventListener('click',e=>{
 const b=e.target.closest?.('[data-campaign-captive]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();const c=data.campaigns.find(c=>c.id===b.dataset.campaignId);if(!c)return;
 const action=b.dataset.campaignCaptive;
 if(action==='add')return open(c.id);
 if(action==='legacy-release'){const g=gangs(c).find(g=>g.id===b.dataset.gang);return legacyRelease(c,g,g?.fighters?.find(f=>f.id===b.dataset.fighter));}
 const holder=gangs(c).find(g=>g.id===b.dataset.holder),r=holder?.campaignCaptives?.find(r=>r.id===b.dataset.record&&active(c,r));if(!r)return;
 if(action==='release')release(c,holder,r);else if(action==='view')view(c,holder,r,b);
},true);
window.MMCampaignCaptives={section,open,records,gangs};
})();
